CREATE TABLE "impact_snapshot" (
	"closed_at" timestamp with time zone NOT NULL,
	"coverage" text NOT NULL,
	"coverage_reason" text,
	"definition_hash" text NOT NULL,
	"department_id" integer,
	"id" integer PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY (sequence name "impact_snapshot_id_seq" INCREMENT BY 1 MINVALUE 1 MAXVALUE 2147483647 START WITH 1 CACHE 1),
	"measure" text NOT NULL,
	"semester_term" "semester_term" NOT NULL,
	"semester_year" integer NOT NULL,
	"source" text NOT NULL,
	"source_ref" text,
	"value" integer NOT NULL,
	CONSTRAINT "impact_snapshot_cell_unique" UNIQUE NULLS NOT DISTINCT("measure","semester_term","semester_year","department_id"),
	CONSTRAINT "impact_snapshot_measure" CHECK ("measure" in ('assistantsPlaced', 'placements', 'schoolsServed')),
	CONSTRAINT "impact_snapshot_coverage" CHECK (("coverage" = 'complete' and "coverage_reason" is null) or ("coverage" = 'incomplete' and "coverage_reason" is not null)),
	CONSTRAINT "impact_snapshot_source" CHECK ("source" in ('legacy-import', 'reimagined')),
	CONSTRAINT "impact_snapshot_value" CHECK ("value" >= 0)
);
